class LibraryMember{private static int counter=100,membersEnrolled=0;protected final String memberNumber;protected int borrowLimit;private int booksBorrowed;private String lastGenre="Not specified";public LibraryMember(int l){if(l<=0)throw new IllegalArgumentException("Borrow limit must be positive");counter++;memberNumber="LIB-"+counter;membersEnrolled++;borrowLimit=l;}public void borrowBook(){if(booksBorrowed<borrowLimit)booksBorrowed++;}public void borrowBook(String g){lastGenre=g;borrowBook();}public int getBooksBorrowed(){return booksBorrowed;}public String getMemberNumber(){return memberNumber;}public String getLastGenre(){return lastGenre;}public static int getMembersEnrolled(){return membersEnrolled;}public static boolean isValidRenewalCode(String c){return c!=null&&c.length()==4&&c.charAt(0)=='R'&&Character.isDigit(c.charAt(1))&&Character.isDigit(c.charAt(2))&&Character.isUpperCase(c.charAt(3))&&Character.isLetter(c.charAt(3));}}
class FacultyMember extends LibraryMember{private String department;public FacultyMember(int l,String d){super(l);department=d;}public String getDepartment(){return department;}}
public class NightlyAudit{static String processNightlyAudit(LibraryMember[] a){int p=0,n=0,f=0,r=0;for(LibraryMember m:a){if(m==null){n++;continue;}p++;if(m instanceof FacultyMember)f++;else r++;}return p+" processed | "+n+" null skipped | "+f+" faculty | "+r+" regular";}public static void main(String[] args){LibraryMember m=new LibraryMember(3);System.out.println(m.getMemberNumber());System.out.println(LibraryMember.getMembersEnrolled());System.out.println(LibraryMember.isValidRenewalCode("R12A"));System.out.println(LibraryMember.isValidRenewalCode("R1A"));System.out.println(LibraryMember.isValidRenewalCode("X12A"));m.borrowBook();m.borrowBook("Fiction");System.out.println(m.getBooksBorrowed());System.out.println(processNightlyAudit(new LibraryMember[]{new FacultyMember(5,"Physics"),null,new LibraryMember(3)}));}}